"use client";
import { useId, useState, type ReactNode } from "react";
import "./focus-lanes.css";
import { useControllableState } from "./use-controllable-state";
export interface LaneEvent {
  id: string;
  row: number;
  label: string;
  detail?: ReactNode;
}
export interface FocusLane {
  id: string;
  title: string;
  color: string;
  events: LaneEvent[];
}
/** All lanes share row coordinates. Focus changes width; it never repacks events. */
export interface FocusLanesProps {
  lanes: FocusLane[];
  rows?: number;
  duration?: number;
  onSelect?: (id: string) => void;
  value?: string;
  defaultValue?: string;
  onValueChange?: (id: string) => void;
  selectedId?: string | null;
  className?: string;
  style?: React.CSSProperties;
}
export function FocusLanes({
  lanes,
  rows = 5,
  onSelect,
  duration,
  value,
  defaultValue,
  onValueChange,
  selectedId,
  className = "",
  style,
}: FocusLanesProps) {
  const [focused, setFocused] = useControllableState(
    value,
    defaultValue ?? lanes[0]?.id ?? "",
    onValueChange,
  );
  const [selected, setSelected] = useControllableState(
    selectedId,
    null as string | null,
    onSelect
      ? (id) => {
          if (id !== null) onSelect(id);
        }
      : undefined,
  );
  const instance = useId();
  return (
    <div
      className={`roc-lanes ${className}`}
      style={
        {
          height: rows * 45 + 44,
          "--roc-duration": duration ? `${duration}ms` : undefined,
          ...style,
        } as React.CSSProperties
      }
    >
      {lanes.map((lane) => (
        <section
          key={lane.id}
          className={`roc-lane ${focused === lane.id ? "is-focused" : ""}`}
          style={{ "--lane-color": lane.color } as React.CSSProperties}
        >
          <button
            type="button"
            className="roc-lane-heading"
            aria-expanded={focused === lane.id}
            aria-controls={`${instance}-${lane.id}`}
            onClick={() => setFocused(lane.id)}
            title={lane.title}
          >
            <span className="roc-lane-dot" />
            <span className="roc-lane-title">{lane.title}</span>
          </button>
          <div className="roc-lane-events" id={`${instance}-${lane.id}`}>
            {lane.events.map((event) => (
              <button
                type="button"
                key={event.id}
                className={`roc-lane-event ${selected === event.id ? "is-selected" : ""}`}
                style={{ top: event.row * 45 }}
                title={event.label}
                aria-label={`${lane.title}: ${event.label}`}
                aria-pressed={selected === event.id}
                onClick={() => {
                  setFocused(lane.id);
                  setSelected(event.id);
                }}
              >
                <span className="roc-event-dot" />
                <span className="roc-event-label">{event.label}</span>
              </button>
            ))}
          </div>
        </section>
      ))}
    </div>
  );
}

@import "./surface.css";
.roc-lanes * {
  box-sizing: border-box;
}
.roc-lanes button {
  font: inherit;
  color: inherit;
  cursor: pointer;
}
.roc-lanes {
  display: flex;
  width: 100%;
  min-width: 250px;
  overflow: hidden;
  border: 1px solid var(--roc-line, #d8dcd4);
  border-radius: var(--roc-radius, 8px);
  background: var(--roc-paper, #fcfdf9);
}
.roc-lane {
  position: relative;
  flex: 0 0 45px;
  min-width: 0;
  border-right: 1px solid var(--roc-line, #d8dcd4);
  transition:
    flex-basis 0.48s cubic-bezier(0.22, 0.8, 0.25, 1),
    flex-grow 0.48s cubic-bezier(0.22, 0.8, 0.25, 1);
  overflow: hidden;
}
.roc-lane:last-child {
  border: 0;
}
.roc-lane.is-focused {
  flex: 1 1 0;
}
.roc-lane-heading {
  height: 44px;
  width: 100%;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 16px;
  background: none;
  border: 0;
  border-bottom: 1px solid var(--roc-line, #d8dcd4);
  font-size: 12px !important;
  text-align: left;
  white-space: nowrap;
}
.roc-lane-dot,
.roc-event-dot {
  flex: none;
  display: block;
  width: 9px;
  height: 9px;
  background: var(--lane-color);
  border-radius: 2px;
}
.roc-lane-title,
.roc-event-label {
  opacity: 0;
  filter: blur(2px);
  transition:
    opacity 0.25s ease-in-out,
    filter 0.25s ease-in-out;
}
.roc-lane-events {
  position: relative;
}
.roc-lane-event {
  position: absolute;
  left: 0;
  right: 0;
  height: 38px;
  display: flex;
  align-items: center;
  gap: 12px;
  text-align: left;
  border: 0;
  background: none;
  padding: 0 16px;
  overflow: hidden;
  white-space: nowrap;
  font-size: 11px !important;
}
.roc-lane-event:hover,
.roc-lane-event.is-selected {
  background: #edf0e7;
}
.roc-event-dot {
  width: 12px;
  height: 18px;
}
.roc-event-label {
  white-space: nowrap;
}
@media (prefers-reduced-motion: reduce) {
  .roc-lanes * {
    transition: none !important;
    animation: none !important;
  }
}
.roc-lane {
  transition:
    flex-basis var(--roc-duration, 480ms) cubic-bezier(0.22, 0.8, 0.25, 1),
    flex-grow var(--roc-duration, 480ms) cubic-bezier(0.22, 0.8, 0.25, 1);
}
@media (prefers-reduced-motion: reduce) {
  .roc-lane {
    transition: none !important;
  }
}

.roc-lane.is-focused .roc-lane-title,
.roc-lane.is-focused .roc-event-label {
  opacity: 1;
  filter: blur(0);
}

@import "./animation.css";
@import "./corners.css";
@import "./responsive.css";
/* Shared surface primitives only. Tokens inherit from the host. No page reset. */
:where(
  .roc-expand,
  .roc-folder,
  .roc-sources,
  .roc-lanes,
  .roc-tabs,
  .roc-card-preview,
  .roc-image-viewport,
  .roc-voice,
  .roc-selection-toolbar,
  .roc-page-book,
  .roc-source-tray
) {
  color: var(--roc-ink, #30332e);
  font-family: inherit;
  box-sizing: border-box;
}
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  * {
  box-sizing: border-box;
}
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  button {
  font: inherit;
  color: inherit;
  cursor: pointer;
}
.roc-image-viewport:focus-visible,
.roc-page-book:focus-visible,
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  button:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 2px var(--roc-focus, #737373) !important;
}
@media (forced-colors: active) {
  .roc-image-viewport:focus-visible,
  .roc-page-book:focus-visible,
  :where(
      .roc-expand,
      .roc-folder,
      .roc-sources,
      .roc-lanes,
      .roc-tabs,
      .roc-card-preview,
      .roc-image-viewport,
      .roc-voice,
      .roc-selection-toolbar,
      .roc-page-book,
      .roc-source-tray
    )
    button:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }
}
.roc-eyebrow {
  font:
    10px/1.4 ui-monospace,
    monospace;
  letter-spacing: 0.12em;
  color: var(--roc-muted, #757b72);
}
.roc-text-button {
  border: 0;
  background: none;
  padding: 9px 0;
  font-size: 12px;
  text-align: left;
  display: inline-flex;
  gap: 20px;
  align-items: center;
}

/* ROC owns motion; Base UI owns interaction and portal presence. */
/* These parts use spring positions, so a CSS transition would lag the pointer. */
.roc-ui[data-slot="slider-thumb"],
.roc-ui[data-slot="slider-range"] {
  transition-property: background-color, border-color, box-shadow;
}
/* Static content stays still; interactive surfaces respond to state changes. */
:where(.roc-ui, .roc-shadcn):is(
  [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
  [data-slot="table-row"], [data-slot="sidebar-menu-button"]
) {
  transition: background-color 150ms ease-out, border-color 150ms ease-out,
    box-shadow 150ms ease-out;
}
@media (prefers-reduced-motion: reduce) {
  :where(.roc-ui, .roc-shadcn):is(
    [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
    [data-slot="table-row"], [data-slot="sidebar-menu-button"]
  ) { transition: none; }
}

/* Smooth squircle corners, following the visual treatment at https://corne.rs/.
   Native corner shaping keeps borders, shadows and overflowing content intact.
   Browsers without support retain the existing border-radius fallback. */
:where(
  [class^="roc-"],
  [class*=" roc-"],
  [class^="roc-"] *,
  [class*=" roc-"] *
) {
  /* ROC limits by role, informed by Apple's compact-control and surface guidance.
     These are ROC values, not platform-prescribed dimensions. Zero stays square. */
  --roc-radius-compact: min(var(--roc-radius, 9px), 8px);
  --roc-radius-control: min(var(--roc-radius, 9px), 10px);
  --roc-radius-popup: min(var(--roc-radius, 9px), 12px);
  --roc-radius-surface: min(var(--roc-radius, 12px), 20px);
}
@supports (corner-shape: squircle) {
  :where(
    [class^="roc-"],
    [class*=" roc-"],
    [class^="roc-"] *,
    [class*=" roc-"] *
  ) {
    corner-shape: var(--roc-corner-shape, squircle);
  }
}

/* Shared viewport constraints for portalled controls, including standalone consumers. */
:is(.roc-ui, .roc-shadcn)[data-slot]:is(
  [data-slot="popover-content"],
  [data-slot="hover-card-content"],
  [data-slot="tooltip-content"],
  [data-slot="select-content"],
  [data-slot="combobox-content"],
  [data-slot="dropdown-menu-content"],
  [data-slot="dropdown-menu-sub-content"],
  [data-slot="context-menu-content"],
  [data-slot="context-menu-sub-content"],
  [data-slot="menubar-content"],
  [data-slot="menubar-sub-content"]
) {
  max-inline-size: min(var(--available-width, calc(100vw - 24px)), calc(100vw - 24px));
  max-block-size: min(var(--available-height, calc(100dvh - 24px)), calc(100dvh - 24px));
  overflow: auto;
  overflow-wrap: anywhere;
  overscroll-behavior: contain;
}
@media (max-width: 640px), (pointer: coarse) {
  .roc-ui.roc-ui-button[data-slot],
  .roc-ui[data-slot="native-select"],
  .roc-shadcn[data-slot="select-trigger"] {
    min-height: 44px;
  }
  .roc-ui.roc-ui-button[data-size^="icon"] {
    width: 44px;
    height: 44px;
  }
  .roc-ui[data-slot="input"],
  .roc-ui[data-slot="textarea"],
  .roc-shadcn[data-slot="input-group-control"] {
    font-size: 16px;
  }
  .roc-ui[data-slot="input"],
  .roc-shadcn[data-slot="input-group"],
  .roc-ui[data-slot="slider"] {
    min-height: 44px;
  }
  .roc-shadcn[data-slot="input-group"] [data-slot="input-group-control"] {
    min-height: 42px;
  }
  .roc-sidebar-link,
  .roc-ui[data-slot="tabs-trigger"],
  .roc-ui[data-slot="toggle"],
  .roc-shadcn[data-slot="select-item"],
  .roc-shadcn[data-slot="combobox-item"] {
    min-height: 44px;
  }
  .roc-ui[data-slot="dropdown-menu-item"],
  .roc-ui[data-slot="dropdown-menu-checkbox-item"],
  .roc-ui[data-slot="dropdown-menu-radio-item"],
  .roc-shadcn[data-slot="context-menu-item"],
  .roc-shadcn[data-slot="menubar-item"] {
    min-height: 44px;
  }
}

"use client";
import { useState } from "react";
/** An optional owner, not a mandatory store or application provider. */
export function useControllableState<T>(
  value: T | undefined,
  defaultValue: T,
  onChange?: (value: T) => void,
): [T, (next: T) => void] {
  const [local, setLocal] = useState(defaultValue),
    current = value === undefined ? local : value;
  return [
    current,
    (next) => {
      if (Object.is(current, next)) return;
      if (value === undefined) setLocal(next);
      onChange?.(next);
    },
  ];
}
